*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/protected_dep_cal.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/jquery-1.11.0.min.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/elastic_search.js");
scwin.MSG_TR_DOME = "작업이 정상적으로 처리되었습니다.";
scwin.MSG_TR_FAIL = "처리 중 오류가 발생하였습니다.";
scwin.vScrenID = "ULDSTF07071.xml";
scwin.vBzProcsNo;
scwin.approvCd;
scwin.procsCd;
scwin.fileYn = "N";
scwin.instYn = "N";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //보호예수인출승인, 재보호예수가 없을 경우 승인시 보호예수T 에 update

scwin.fn_load = function() {
    if (dts_detail.getCellData(1, "LST_APPROV_YN") == "2") {
        //제출완료

        $c.stf.showObj(btn_acpt, true); //접수
        $c.stf.showObj(btn_Save, false); //인출승인 or 최종확인
        $c.stf.showObj(panel_1, false); //파일저장
        scwin.approvCd = "3";

        /*if(dts_detail.NameString(1,"LIST_PROCS_STAT_CD") == "38"){
        	showObj(btn_Reject, false);//반려
        }else{
        	showObj(btn_Reject, true);//반려
        }*/
        $c.stf.showObj(btn_Reject, true); //반려

        if (dts_detail.getCellData(1, "LIST_PROCS_STAT_CD") == "32" ||
            dts_detail.getCellData(1, "LIST_PROCS_STAT_CD") == "35" ||
            dts_detail.getCellData(1, "LIST_PROCS_STAT_CD") == "37") {
            scwin.procsCd = "33";
        } else {
            scwin.procsCd = dts_detail.getCellData(1, "LIST_PROCS_STAT_CD");
        }
    } else if (dts_detail.getCellData(1, "LST_APPROV_YN") == "3") {
        //접수완료
        if (dts_detail.getCellData(1, "PRTDEPO_REOPN_YN") == "Y") {
            //재보호예수가 있음 - 인출승인
            if (dts_detail.getCellData(1, "LIST_PROCS_STAT_CD") == "38") {
                $c.stf.showObj(btn_acpt, false); //접수
                $c.stf.showObj(btn_Reject, false); //반려
                $c.stf.showObj(btn_Save, true); //인출승인 or 최종확인
                $c.stf.showObj(panel_1, false); //파일저장
                btn_Save.src = "/img/btn_confirm.gif"; //최종확인버튼
                scwin.approvCd = "9";
                scwin.procsCd = "39";
            }
            //수정요청, 수정승인시
            else if (dts_detail.getCellData(1, "LIST_PROCS_STAT_CD") == "34" || dts_detail.getCellData(1, "LIST_PROCS_STAT_CD") == "35") {
                $c.stf.showObj(btn_acpt, false);
                $c.stf.showObj(btn_Reject, false);
                $c.stf.showObj(btn_Save, false);
                $c.stf.showObj(panel_1, false); //파일저장

            } else {
                $c.stf.showObj(btn_acpt, false); //접수
                $c.stf.showObj(btn_Reject, false); //반려
                $c.stf.showObj(btn_Save, true); //인출승인 or 최종확인
                $c.stf.showObj(panel_1, true); //파일저장
                btn_Save.src = "/img/btn_approval.gif"; //인출승인 버튼 
                scwin.approvCd = "8";
                scwin.procsCd = "38";
                scwin.instYn = "Y";
            }
        } else {
            //재보호예수가 없음 - 최종확인
            $c.stf.showObj(btn_acpt, false); //접수
            $c.stf.showObj(btn_Reject, false); //반려
            $c.stf.showObj(btn_Save, true); //인출승인 or 최종확인
            $c.stf.showObj(panel_1, true); //파일저장
            btn_Save.src = "/img/btn_confirm.gif"; //최종확인버튼
            scwin.approvCd = "9";
            scwin.procsCd = "39";
            scwin.instYn = "Y";
        }
    } else {
        $c.stf.showObj(btn_acpt, false);
        $c.stf.showObj(btn_Reject, false);
        $c.stf.showObj(btn_Save, false);
        $c.stf.showObj(panel_1, false); //파일저장

    }
};
scwin.fn_check = function() {
    if ($c.stf.getObjectValue(txb_file5) == "") {
        $c.win.alert("[처분승인공문]을 선택하세요.");
        txb_file5.focus();
        return false;
    }
};
scwin.fn_list_sync = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=PRTDEPOWITHD_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstinvstg.prtdepowithd.detail.select" + "&{P}param01=" + scwin.vBzProcsNo;
    dts_detail.DataID = encodeURI(url);
    dts_detail.Reset();
};
scwin.fn_fileList = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=PRTDEPOWITHD_ATTACH_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstinvstg.prtdepowithd.attach1.select" + "&{P}param01=" + scwin.vBzProcsNo;
    dts_fileList.DataID = encodeURI(url);
    dts_fileList.Reset();
};
scwin.fn_file5 = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=PRTDEPOWITHD_DATA_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstinvstg.prtdepowithd.attach5.select" + "&{P}param01=" + scwin.vBzProcsNo;
    dts_file5.DataID = encodeURI(url);
    dts_file5.Reset();
};



//파일 다운로드
scwin.fn_filedown = function(attach_seq, prtdepo_Id, prtdepo_seq) {
    if (js_dep_cd == '2500' || js_dep_cd == '2520' || js_dep_cd == '2540' ||
        js_dep_cd == '3300' || js_dep_cd == '3320' || js_dep_cd == '3330' || js_dep_cd == '3350' ||
        js_dep_cd == '3E00' || js_dep_cd == '3E10' || js_dep_cd == '3E20' || js_dep_cd == '3E30' || js_dep_cd == '3E40' ||
        js_dep_cd == '3B00' || js_dep_cd == '3B30' || js_dep_cd == '2615' || js_dep_cd == '3G20') {
        location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&prtdepo_Id=" + prtdepo_Id + "&prtdepo_seq=" + prtdepo_seq + "&attach_seq=" + attach_seq + "&gubun=27";
    } else {
        $c.win.alert('파일 열람 권한이 없습니다');
    }
};



//파일첨부 head
scwin.fn_setDataHeader = function() {

    //dts_file5.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

};


//파일저장
scwin.fn_FileSave = function() {
    var pdid = dts_detail.getCellData(1, "PRTDEPO_ID");
    var id_seq = dts_detail.getCellData(1, "PRTDEPO_WITHD_APPL_SEQ");
    var type = "I";
    var filename = dts_file5.getCellData(1, "filename");
    if (filename == null || filename == "undefined" || filename.length == 0) vDispOfcdoc = true;
    trs_File.Action = "/lstinvstg/PrtDepo.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=createFile&pdid=" + pdid + "&id_seq=" + id_seq + "&joyType=" + type;
    trs_File.KeyName = "toinb_dataid4";
    trs_File.KeyValue = "JSP(I:pFile=dts_file5)";
    trs_File.Post();
};
scwin.fn_saveType = function(jobType) {
    var rtn;
    var fileCheck = "N";

    //접수
    if (jobType == "A") {
        //접수
        rtn = confirm('의무보유주식의 처분을 접수하시겠습니까?');
    } else if (jobType == "R") {
        //반려
        rtn = confirm('의무보유주식의 처분을 반려 하시겠습니까?');
        scwin.approvCd = "7";
        //procsCd = "37";
        if (dts_detail.getCellData(1, "LIST_PROCS_STAT_CD") == "38") {
            scwin.procsCd = "38";
        } else {
            scwin.procsCd = "37";
        }
    } else if (jobType == "S") {
        //승인

        if (dts_detail.getCellData(1, "LIST_PROCS_STAT_CD") < "38") {
            scwin.fileYn = "Y";
            if (txb_file5.getValue() == "") {
                $c.win.alert('처분승인공문을 첨부하여 주십시오.');
                return;
            }
        }
        if (scwin.approvCd == "9") {
            rtn = confirm('최종확인 하시겠습니까?');
            if (scwin.instYn == "Y") fileCheck = "Y"; //재보호예수가 없을 경우 승인파일을 첨부하고 최종승인 됨.

        } else {
            rtn = confirm('처분승인 하시겠습니까?');
            fileCheck = "Y";
        }
    }
    if (rtn == 1) {
        if (fileCheck == "Y") {
            scwin.fn_FileSave();
        } else {
            scwin.fn_save();
        }
    }
};
scwin.fn_save = function() {
    //바뀌는 상태
    dts_detail.setCellData(1, "LST_APPROV_YN", scwin.approvCd);
    dts_detail.setCellData(1, "LIST_PROCS_STAT_CD", scwin.procsCd);
    dts_detail.setCellData(1, "INST_YN", scwin.instYn);
    trs_Save.Action = $c.lc.fn_encodeNSession("/lstinvstg/PrtDepo.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&method=savePrtDepoWithd");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInpReqInf=dts_detail)";
    trs_Save.Post();
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
scwin.indexingElasitcSearch = function() {
    prtdepo_withd_attach(dts_detail.getCellData(1, "PRTDEPO_ID"), dts_detail.getCellData(1, "PRTDEPO_WITHD_APPL_SEQ"));
};
scwin.dts_detail_OnLoadCompleted = function(rowcount) {
    scwin.fn_load();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert(scwin.MSG_TR_FAIL);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert(scwin.MSG_TR_DOME);
    scwin.fn_list_sync();
    scwin.fn_fileList();
    scwin.fn_file5();
    //목록다시뿌림
    scwin.fn_parentRefresh();
};
scwin.trs_File_OnFail = function() {
    $c.win.alert(scwin.MSG_TR_FAIL);
};
scwin.trs_File_OnSuccess = function() {
    scwin.fn_file5();
    scwin.indexingElasitcSearch();
    scwin.fn_save();
};
scwin.btn_lineadd_onclick = function() {
    if (dts_file5.getCellData(1, "filename") == "") {
        dts_file5.insertRow();
        inf_find.open();
        if (inf_find.getValue() != "") {
            dts_file5.setCellData(1, "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
            txb_file5.setValue(inf_find.getValue());
        } else {
            $c.cp.removeRow(dts_file5, 1);
            txb_file5.setValue("");
        }
    }
};
scwin.dts_file5_OnLoadCompleted = function(rowcount) {
    txb_fileseq.setValue(dts_file5.getCellData(1, "fileseq"));
    txb_file5.setValue(dts_file5.getCellData(1, "filename"));
};
scwin.inf_find_OnClick = function() {

};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_acpt_onclick = function() {
    scwin.fn_saveType("A");
};
scwin.btn_Reject_onclick = function() {
    scwin.fn_saveType("R");
};
scwin.btn_Save_onclick = function() {
    scwin.fn_saveType("S");
};
scwin.grd_userlist_OnDblClick = function(row, colid) {
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0) {
        scwin.fn_filedown(dts_fileList.getCellData(row, "ATTACH_FILE_SEQ"), dts_fileList.getCellData(row, "PRTDEPO_ID"), dts_fileList.getCellData(row, "PRTDEPO_WITHD_APPL_SEQ"));
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    $c.stf.showObj(inf_find, false);
    $c.stf.showObj(txb_fileseq, false);
    var parentWin = $c.frame.path("../");
    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.fn_list_sync();
    scwin.fn_fileList();
    scwin.fn_file5();
    scwin.fn_setDataHeader();
    var parentFrameID = $c.stf.getQuery(frame.srcUrl, "frameID");
    if (parentFrameID.indexOf('STF60000') != -1) {
        $c.stf.showObj(btn_acpt, false);
        $c.stf.showObj(btn_Reject, false);
        $c.stf.showObj(btn_Save, false);
        $c.stf.showObj(btn_lineadd, false);
    }
};
